          "Homens Glydar geralmente não usam barba cheia. Barba grande molha, pesa, coça e atrapalha. O mais comum é rosto quase limpo, barba curta, queixo ralo ou bigode discreto. Entre os mais ricos, o rosto bem aparado também comunica cuidado e estatuto.",
          "O cabelo costuma ficar preso, muitas vezes húmido, amarrado com fibra, tira de couro ou corda fina. Cabelo solto é incômodo em barco e ponte. As mulheres também prendem o cabelo em nós, tranças simples ou voltas apertadas.",
