          "O título “Lorde” é real entre eles, embora não signifique o mesmo tipo de nobreza dos Polar. É um título ribeirinho, ligado a casa, cais, herança e reconhecimento prático.",
          "Ossar não manda em todos os Glydar como um rei. Mas representa o clã porque sua cidade é a maior, sua família controla o cais mais influente e as vilas menores sabem que, se ele cair, os outros clãs falarão com elas uma por uma."
