          "É um homem de meia-idade, largo de ombros, cabelo preso por cordas escuras, barba curta ou quase rala, olhos sempre desconfiados e roupas melhores do que as dos pescadores, mas sem luxo de salão Polar. Usa tecido de linhava de boa qualidade, cordas finas e um Nó de Margem duplo no pulso.",
          "Ossar não é calmo de verdade. Parece calmo porque passou a vida tentando não demonstrar pânico.",
          "Ele é tenso, inseguro, prudente demais e profundamente desconfiado. Herdou o cargo e a filosofia dos pais: não mexer com clãs maiores, não desafiar Kaendar sem necessidade, pagar o que for preciso, manter peixe saindo, manter barcos inteiros, manter o povo vivo.",
          "Para Ossar, neutralidade não é ideal bonito. É hábito de família.",
