          "Ele entra na aliança por medo de Kaendar controlar completamente o rio.",
          "Mas quando percebe que a aliança é mal estruturada, cheia de desconfiança e sustentada por vingança mais do que plano, suas inseguranças crescem. Depois do ataque do óleo na água, sente culpa e medo da reacção Polar.",
          "Sua grande falha é tentar ficar neutro ou aderir ao lado que acredita que vencerá a guerra. Essa tentativa de preservar o povo pode acabar penalizando o próprio povo.",
