          "Varael acredita que os Glydar não devem pagar com suas margens por uma guerra que nasceu entre Fendelar, Tondrar, Buldar e Polar. Defende retirada, negociação e tentativa de restaurar relações com Kaendar antes que Alyra use o óleo como desculpa.",
