          "Mas esse atraso raramente é simples lentidão. Entre os Cendar, esperar é uma forma de medir. Mede-se fome. Mede-se medo. Mede-se arrogância. Mede-se pressa. Mede-se mentira. Um estrangeiro apressado demais pode estar fugindo, escondendo algo ou tentando empurrar o clã para o campo que escolheu. Os Cendar aprenderam a sobreviver recusando o tempo dos outros.",
