          "Como os outros clãs principais de Jesed, os Cendar descendem, em algum grau, dos sobreviventes antigos da queda de Etérea. Essa memória perdeu-se quase por completo. Em Guerras de Sangue, os Cendar não têm lembrança clara dos céus, nem tratam a própria origem como descendência divina ou elevada.",
          "A história deles tornou-se baixa, territorial e prática. Enquanto outros povos fixaram-se junto a rios, campos férteis, forjas, gargantas secas ou florestas densas, os antepassados Cendar encontraram uma região difícil: pântanos, campos húmidos, colunas de pedra, bosques de madeira flexível, caminhos que afundavam, montes estreitos e passagens que mudavam conforme a estação.",
