          "Os Urtistar surgiram de um antigo clã grande que se partiu. Esse antigo povo ocupava uma região extensa no oeste, perto das bordas secas e dos caminhos que levam ao deserto e a outros clãs do noroeste. Quando houve a separação, as terras ficaram divididas de forma instável entre três forças: os Urtistar, o clã que se separou deles e um terceiro clã que já ocupava parte da região.",
