          "Essa punição é uma das mais temidas do clã, porque não é apenas física. É espiritual e social. Uma mulher que perde a língua perde a relação com a palavra sagrada, perde pureza, perde autoridade e passa a existir como aviso vivo. A punição reforça a crença de que a palavra deve atravessar a mulher sem ser corrompida por vontade própria.",
          "Para os Urtistar, isso é santidade.",
          "Para outros clãs, é horror."
