          "A pobreza Urtistar reforça isso. Os mais pobres lutam para ganhar dignidade. Um homem sem riqueza, sem grande Casa, sem animais próprios e sem prestígio pode encontrar na guerra uma forma de se tornar lembrado. Isso alimenta o fervor militar, a obediência religiosa e o desprezo pela morte.",
          "A morte honrada não apaga todas as desigualdades, mas pode elevar uma família. Um guerreiro pobre que morre bem pode deixar nome, carne garantida por algum tempo aos filhos, respeito da Casa e lugar em memória ritual.",
