          "Os Urtistar criam muitos animais. Parte serve para carne. Parte serve para leite, gordura, couro, carga, montaria, guarda e comércio. A criação animal veio em parte da absorção violenta do conhecimento Arvaktar, depois transformado em orgulho Urtistar.",
