          "Os Urtistar compram alguns alimentos vegetais, grãos e produtos que não produzem bem. Também usam terras secas para criação animal e depois consomem os animais. A dieta é marcada por carne, gordura, leite espesso, raízes duras, plantas de viagem e alimentos comprados quando necessário."
