        "paragraphs": [
          "Os Urtistar fazem contratos, mas não são definidos por eles como os outros povos imaginam.",
          "Para estrangeiros, contratar Urtistar é pagar por protecção. Para os Urtistar, aceitar contrato é avaliar conveniência. O contrato pode ser cumprido com lealdade assustadora, mas a fé e o interesse do clã estão acima de qualquer promessa feita a impuros ou estrangeiros.",
          "Isso cria uma contradição aparente:",
          "eles punem severamente quem quebra contrato dentro do clã;",
          "mas podem justificar a quebra de acordos externos se a fé ou os capitães declararem necessidade.",
          "Um Urtistar que quebra contrato sem autorização pode ser executado.",
          "Um capitão que quebra contrato por interesse religioso pode ser celebrado.",
          "A diferença não está no acto. Está na autoridade."
        ]
