          "Os Cendar representam a fronteira que os Urtistar não conseguiram atravessar. Representam pedra, espera, engenho manual, mulheres guerreiras e defesa paciente. Tudo isso irrita os Urtistar. Para eles, os Cendar são obstáculos arrogantes, um povo que se esconde atrás de portões, pântanos, mecanismos e prudência.",
          "Os Cendar, por sua vez, veem os Urtistar como ameaça religiosa, violenta e imprevisível.",
          "Os dois povos não se entendem."
