          "Além disso, alguns Vendrar falam Veshari ou fragmentos da língua antiga, o que cria uma ligação rara e desconfortável. Os Urtistar podem desprezar os Vendrar por venderem demais, mas sabem que eles preservam coisas antigas que outros povos perderam."
