          "Essa combinação é perigosa. Kahul não precisa gritar religião o tempo todo para ser religioso. Ele acredita. A fé não é ornamento na fala dele; é estrutura de pensamento. Ao mesmo tempo, sabe negociar, esperar, calcular e escolher momento.",
          "Kahul apoia movimentos contra Kaendar por oportunidade de lucro, interesse político e ameaça à autonomia Urtistar. Se Kaendar controla rotas, regula escoltas e enfraquece capitães, os Urtistar perdem parte da sua identidade. Mas, para Kahul, isso também pode ser lido religiosamente: um povo que tenta prender a lâmina Urtistar tenta impedir o caminho observado pelo Olho.",
          "Kahul deve parecer homem de poucas palavras, barba marcada, adornos no corpo, olhar fixo e presença incômoda. Quando fala, deve parecer que já aceitou consequências que outros ainda estão tentando evitar.",
