        "number": "21",
        "title": "Resumo final do clã",
        "paragraphs": [
          "Os Urtistar são um clã de cavernas, fé antiga, lâminas, animais, couro, carne e medo.",
          "Vieram de um povo maior, o Veshadar, dividido por diferença de pensamento. Extinguiram dois povos irmãos, Arvaktar e Kardar, e orgulham-se disso. Tentaram expandir contra os Cendar, mas foram parados. Também tiveram a expansão limitada pelos Polar. Desde então, vivem dentro de limites que não amam, mas aceitaram pela força.",
          "A sua cidade principal, Urtar-Vesh, fica dentro de cavernas com salões, clareiras de luz, tochas, currais, pátios de treino e câmaras sagradas. A entrada selada vale mais do que muralha.",
          "A sociedade é governada por sete capitães de Casas de sangue. Os homens lutam. As mulheres são sagradas, não guerreiras, e só elas podem portar e ler as escrituras. Essas escrituras foram criadas por homens antigos, mas os Urtistar acreditam que vieram do deus deles, o Olho de Vesh. Uma mulher portadora que mente tem a língua cortada e perde pureza.",
          "A economia vem de animais, carne seca, couro, gordura, contratos, escoltas e intimidação. Compram armas dos Polar e fazem bons negócios com Vendrar. Têm pouca relação com Buldar, contacto útil com Glydar, comércio raro com Tondrar e ódio antigo pelos Cendar.",
          "Em guerra, usam lâminas curtas, lâminas curvas, duas lâminas, facas arremessadas, ataques precisos e medo. São excelentes guerreiros em qualquer lugar, não apenas em terreno próprio.",
          "A sua virtude é coragem absoluta.",
          "A sua corrupção é fanatismo imprevisível.",
          "Frase final:",
          "Os Urtistar são o povo que vive sob o olho: criam animais nas sombras da pedra, secam carne para a estrada, guardam escrituras que não compreendem por completo, matam por fé e fazem do medo a língua que todos os clãs entendem."
        ]
